import{_ as o,o as e,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Crimson/SeaStore 2021-06-02","description":"","frontmatter":{"title":"Ceph Crimson/SeaStore 2021-06-02","date":"2021-06-02T00:00:00.000Z","updated":"2021-06-03T00:00:00.000Z","tags":["Ceph","分布式存储","Crimson OSD","错误报告","Scrubbing PR","Clang 编译问题","可中断分配器","扩展放置管理器","键值大小限制"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Crimson_SeaStore_2021-06-02.md","filePath":"posts/2021/Ceph_Crimson_SeaStore_2021-06-02.md","lastUpdated":1780459816000}'),l={name:"posts/2021/Ceph_Crimson_SeaStore_2021-06-02.md"};function n(a,r,s,p,g,S){return e(),i("div",null,[...r[0]||(r[0]=[t('<p>在Ceph Crimson/SeaStore的2021年6月2日会议中，研发人员和专家讨论了一系列与Ceph分布式存储系统相关的问题和进展。</p><h3 id="会议要点" tabindex="-1">会议要点： <a class="header-anchor" href="#会议要点" aria-label="Permalink to &quot;会议要点：&quot;">​</a></h3><ol><li><p><strong>Crimson OSD启动失败问题</strong>：会议重点讨论了Crimson OSD在Rook中运行失败的复现和解决方法。上周尝试使用经典设备启动Crimson失败，本周将重点解决启动时的错误报告问题。</p></li><li><p><strong>异常处理与错误报告</strong>：提出使用与Ceph数据库相同的清理函数钩子方法作为修复方案，并解决了ASAN报告的越界访问问题，这是ASAN自身的bug。</p></li><li><p><strong>ZFS学习与研究</strong>：研究ZFS在垃圾收集和分配器问题上的处理方式。</p></li><li><p><strong>事务管理器读取交换断言问题</strong>：修复了因分段状态跟踪器混乱导致的事务管理器读取交换断言问题。</p></li><li><p><strong>OSD停止异常</strong>：发现Crimson OSD在启动后立即停止，正在调试LBA析构函数中的断言问题。</p></li><li><p><strong>新实习生介绍</strong>：介绍了Red Hat的新实习生Joseph，他将在Crimson项目中工作。</p></li><li><p><strong>Scrubbing PR讨论</strong>：讨论了关于Scrubbing的PR，建议重新创建PR以包含最新的基础提交。</p></li><li><p><strong>Clang编译问题修复</strong>：Sam修复了Clang编译问题，计划提交到Clang上游。</p></li><li><p><strong>可中断分配器开发</strong>：继续开发可中断分配器，以便在Ceph存储中使用。</p></li><li><p><strong>扩展放置管理器调试</strong>：正在调试扩展放置管理器，希望本周能提交PR。</p></li><li><p><strong>键值大小限制实现</strong>：实现了键值大小的限制，相关PR已合并。</p></li></ol><h3 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h3><ul><li>继续调试Crimson OSD启动和停止的异常问题。</li><li>重新创建Scrubbing PR以包含最新的基础提交。</li><li>提交Clang编译问题的reproducer到上游。</li></ul><h3 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h3><ul><li>继续调试和修复Crimson OSD相关问题。</li><li>完成Scrubbing PR的重新创建和测试。</li><li>提交Clang编译问题的reproducer。</li><li>继续开发和测试可中断分配器。</li><li>完成扩展放置管理器的调试并提交PR。</li></ul><p>会议在无其他议题的情况下结束，感谢大家的参与。</p>',8)])])}const d=o(l,[["render",n]]);export{_ as __pageData,d as default};
